base=Path(__file__).resolve().parent;out=base/'comparison_20261018';out.mkdir(exist_ok=True);names=['classic','default','nromal-np'];display=['Classic','Default','Normal (nromal-np)'];records={name:json.loads((base/(name+'_20261018')/'analysis/comparison.json').read_text()) for name in names}
summary={};lines=['# Three recordings: Point-LIO vs vendor odometry','','Operator confirmed the same nominal route for all recordings: 3 m forward/back, followed by 5 m forward/back, with waits. All Point-LIO runs use the same existing calibration, extrinsics, zero-lag setting and temporary 4,000-point startup seed. No application changes or per-bag tuning.','','| Recording | 3 m forward PL / vendor | 3 m return PL / vendor | 5 m forward PL / vendor | 5 m return PL / vendor | Final return PL / vendor |','|---|---:|---:|---:|---:|---:|']
for name,label in zip(names,display):
 a=records[name];c3,c5=a['distance_and_return_checks'];o=a['overall_return_check'];audit=json.loads((base/(name+'_20261018')/'input_audit.json').read_text());res=a['replay_result'];h=a['health'];summary[name]={'source_bag':a['source_bag'],'duration_s':audit['duration_s'],'outbound_3m':{who:c3[who]['outbound_horizontal_endpoint_distance_m'] for who in ['point_lio','vendor']},'outbound_5m':{who:c5[who]['outbound_horizontal_endpoint_distance_m'] for who in ['point_lio','vendor']},'return_3m':{who:c3[who]['return_horizontal_offset_m'] for who in ['point_lio','vendor']},'return_5m':{who:c5[who]['return_horizontal_offset_m'] for who in ['point_lio','vendor']},'final_return_xy_m':{who:o[who]['final_horizontal_offset_from_original_start_m'] for who in ['point_lio','vendor']},'final_return_z_m':{who:o[who]['final_vertical_offset_from_original_start_m'] for who in ['point_lio','vendor']},'lio_quiet_hold_p95_radius_range_m':[min(x['lio_position_p95_distance_to_median_m'] for x in a['holds'].values()),max(x['lio_position_p95_distance_to_median_m'] for x in a['holds'].values())],'point_lio_rate_hz':h['average_pose_frequency_hz'],'registered_clouds':res['registered_clouds'],'pose_count':h['lio_poses'],'cloud_delivery_exact':res['cloud_delivery_exact'],'imu_delivery_exact':res['imu_delivery_exact'],'application_unchanged':res['application_unchanged'],'nonfinite_poses':h['nonfinite_pose_values'],'nonincreasing_pose_stamps':h['nonincreasing_pose_stamps'],'largest_step_m':h['lio_step_translation_m']['max'],'largest_rotation_step_deg':h['lio_step_rotation_deg']['max'],'steps_over_15cm':h['steps_over_0_15_m'],'rotation_steps_over_5deg':h['rotation_steps_over_5_deg'],'tf_missing_pose_stamps':h['tf_missing_pose_stamp_count'],'tf_conflicting_parents':res['multiple_tf_parents'],'revisited_floor_checks':a['revisited_start_floor_checks']}
 def pair(obj,key,scale=1,unit='m',digits=2):return f"{obj['point_lio'][key]*scale:.{digits}f} / {obj['vendor'][key]*scale:.{digits}f} {unit}"
 lines += [f"| {label} | {pair(c3,'outbound_horizontal_endpoint_distance_m')} | {pair(c3,'return_horizontal_offset_m',100,'cm',1)} | {pair(c5,'outbound_horizontal_endpoint_distance_m')} | {pair(c5,'return_horizontal_offset_m',100,'cm',1)} | {pair(o,'final_horizontal_offset_from_original_start_m',100,'cm',1)} |"]
lines += ['','PL = recomputed Point-LIO. Each 5 m leg is measured from its own preceding return hold; final return uses the original start. Endpoints use medians within independently selected quiet waits, not maximum travel or integrated speed.','','![Comparison](comparison.png)','','## Replay quality','']
for name,label in zip(names,display):
 s=summary[name];lines += [f"- {label}: {s['duration_s']:.2f} s, {s['pose_count']} poses at {s['point_lio_rate_hz']:.2f} Hz; all replay cloud and calibrated IMU stamps match. Largest pose step {100*s['largest_step_m']:.2f} cm / {s['largest_rotation_step_deg']:.2f} degrees. Nonfinite values {s['nonfinite_poses']}, nonincreasing stamps {s['nonincreasing_pose_stamps']}, TF parent conflicts {s['tf_conflicting_parents']}."]
lines += ['','All three source containers pass chunk decompression, count checks and summary CRC. Chunk payload CRCs are absent. All required mapping payloads were decoded; this does not guarantee every unrelated topic schema. All replays were headless, sequential, 0.5x, localhost-only, without command topics. Code/configuration hashes remained unchanged.','','Per-run reports explain any final TF boundary mismatch. No endpoint measurement uses the very last output sample.','','## Interpretation limits','','- The 3 m / 5 m distances were supplied by the operator; measurement method and uncertainty are unknown. Curved-path endpoint displacement differs from travelled path length.','- Return offsets combine physical endpoint placement error and estimator error. Without surveyed positions, they are not pure drift measurements.','- These short out-and-back routes can cancel some systematic errors. They do not establish long-distance drift or loop closure performance.','- Vendor odometry is a comparison estimate and shares IMU information; it is not ground truth.','- Vertical return agreement does not establish correct absolute height. Reversible outward slopes may include real terrain or map/gravity tilt.','- Zero LiDAR/IMU acquisition-lag correction remains uncalibrated. Successful replay does not prove exact sensor synchronization.','', 'Individual plots, timing audits, hold windows, source hashes and floor consistency:','']
for name,label in zip(names,display):lines += [f"- [{label} report](../{name}_20261018/REPORT.md) · [plot](../{name}_20261018/analysis/comparison.png)"]
extra=json.loads((base/'default_20261018/analysis/default_extra_movement.json').read_text());summary['default']['extra_movement_after_main_return']=extra
first=extra['brief_first_stop'];lines += ['',f"Default includes a brief extra movement around 76–78 s after the main return. Before that movement, at 74.8–75.8 s, its estimated offset was Point-LIO {100*first['point_lio']['horizontal_offset_from_original_start_m']:.2f} cm versus vendor {100*first['vendor']['horizontal_offset_from_original_start_m']:.2f} cm. The final quiet hold in the table is after that movement. Its 14 cm Point-LIO offset cannot all be called drift, and the final-offset bars alone must not be used to rank recording modes. The earlier stop is brief and less quiet."]
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
