for who,dx,col,label in [('point_lio',-.175,'tab:blue','Point-LIO'),('vendor',.175,'tab:orange','Vendor')]:
 vals=[summary[n]['final_return_xy_m'][who]*100 for n in names];ax[0].bar(x+dx,vals,w,color=col,label=label)
 for xx,val in zip(x+dx,vals):ax[0].text(xx,val+.6,f'{val:.1f}',ha='center',fontsize=9)
ax[0].set_xticks(x,['Classic','Default*','Normal']);ax[0].set(ylabel='Horizontal return offset (cm)',title='Final return to original start');ax[0].legend()
xx=np.arange(6);labels=[n+'\n'+str(d)+' m' for n in ['Classic','Default','Normal'] for d in [3,5]]
for who,dx,col,label in [('point_lio',-.175,'tab:blue','Point-LIO'),('vendor',.175,'tab:orange','Vendor')]:
 vals=[100*(summary[n]['outbound_'+str(d)+'m'][who]-d)/d for n in names for d in [3,5]];ax[1].bar(xx+dx,vals,w,color=col,label=label)
ax[1].set_xticks(xx,labels);ax[1].axhline(0,color='black',lw=.8);ax[1].set(ylabel='Difference from reported distance (%)',title='Outbound endpoint displacement vs nominal distance');ax[1].legend()
for aa in ax:aa.grid(axis='y',alpha=.25);aa.set_axisbelow(True)
fig.suptitle('Same Point-LIO settings — no scale fit; *Default includes extra movement after main return',fontsize=11);fig.savefig(out/'comparison.png',dpi=170);fig.savefig(out/'comparison.pdf');plt.close(fig);(out/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,indent=2));print(out/'REPORT.md')
